import{_ as a,a0 as r,w as d,s,ao as u,I as o,a1 as i,A as e,x as t}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const L=JSON.parse('{"title":"如何啓動進入 Linux 命令列 | LCTT x X-CMD","titleTemplate":false,"description":"如何啓動進入 Linux 命令列 | LCTT (201802) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"如何啓動進入 Linux 命令列 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"如何啓動進入 Linux 命令列 | LCTT (201802) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201802/20180115 How To Boot Into Linux Command Line","title":"如何啓動進入 Linux 命令列","tag":"201802","desc":""},"relativePath":"201802/20180115 How To Boot Into Linux Command Line.md","filePath":"[post].md"}'),p={name:"201802/20180115 How To Boot Into Linux Command Line.md"};function m(x,n,g,b,w,f){const l=r("Link");return d(),s("div",null,[n[16]||(n[16]=u('<h1 id="如何啓動進入-linux-命令列" tabindex="-1">如何啓動進入 Linux 命令列 <a class="header-anchor" href="#如何啓動進入-linux-命令列" aria-label="Permalink to “如何啓動進入 Linux 命令列”">​</a></h1><p><img src="http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/how-to-boot-into-linux-command-line_orig.jpg" alt=""></p><p>可能有時候你啓動 Linux 時需要或者希望不使用 GUI（圖形用户界面），也就是沒有 X，而是選擇命令列。不管是什麼原因，幸運的是，直接啓動進入 Linux 命令列 非常簡單。它需要在其他內核選項之後對引導參數進行簡單的更改。此更改將系統引導到指定的運行級別。</p><h3 id="​為什麼要這樣做" tabindex="-1">​為什麼要這樣做？ <a class="header-anchor" href="#​為什麼要這樣做" aria-label="Permalink to “​為什麼要這樣做？”">​</a></h3><p>如果你的系統由於無效配置或者顯示管理器損壞或任何可能導致 GUI 無法正常啓動的情況而無法運行 Xorg，那麼啓動到命令列將允許你通過登錄到終端進行故障排除（假設你知道要怎麼做），並能做任何你需要做的東西。引導到命令列也是一個很好的熟悉終端的方式，不然，你也可以為了好玩這麼做。</p><h3 id="​訪問-grub-菜單" tabindex="-1">​訪問 GRUB 菜單 <a class="header-anchor" href="#​訪問-grub-菜單" aria-label="Permalink to “​訪問 GRUB 菜單”">​</a></h3><p>在啓動時，你需要訪問 GRUB 啓動菜單。如果在每次啓動計算機時菜單未設置為顯示，那麼可能需要在系統啓動之前按住 <code>SHIFT</code> 鍵。在菜單中，需要選擇 Linux 發行版條目。高亮顯示後該條目，按下 <code>e</code> 編輯引導參數。</p>',7)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/gnu-grub_orig.png"},{default:e(()=>[...n[0]||(n[0]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/gnu-grub_orig.png",alt:"zorin os grub menu"},null,-1)])]),_:1})]),n[17]||(n[17]=o("p",null,"較老的 GRUB 版本遵循類似的機制。啓動管理器應提供有關如何編輯啓動參數的説明。",-1)),n[18]||(n[18]=o("h3",{id:"​​指定運行級別",tabindex:"-1"},[t("​​指定運行級別 "),o("a",{class:"header-anchor",href:"#​​指定運行級別","aria-label":"Permalink to “​​指定運行級別”"},"​")],-1)),n[19]||(n[19]=o("p",null,[t("​會出現一個編輯器，你將看到 GRUB 會解析給內核的選項。移動到以 "),o("code",null,"linux"),t(" 開頭的行（舊的 GRUB 版本可能是 "),o("code",null,"kernel"),t("，選擇它並按照説明操作）。這指定了要解析給內核的參數。在該行的末尾（可能會出現跨越多行，具體取決於你的終端分辨率），只需指定要引導的運行級別，即 "),o("code",null,"3"),t("（多用户模式，純文本）。")],-1)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_orig.png"},{default:e(()=>[...n[1]||(n[1]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_orig.png",alt:"customize grub menu"},null,-1)])]),_:1})]),n[20]||(n[20]=o("p",null,[t("按下 "),o("code",null,"Ctrl-X"),t(" 或 "),o("code",null,"F10"),t(" 將使用這些參數啓動系統。開機和以前一樣。唯一改變的是啓動的運行級別。")],-1)),n[21]||(n[21]=o("p",null,"這是啓動後的頁面：",-1)),o("p",null,[i(l,{href:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_1_orig.png"},{default:e(()=>[...n[2]||(n[2]=[o("img",{src:"http://www.linuxandubuntu.com/uploads/2/1/1/5/21152474/runlevel_1_orig.png",alt:"boot linux in command line"},null,-1)])]),_:1})]),n[22]||(n[22]=u('<h3 id="運行級別" tabindex="-1">運行級別 <a class="header-anchor" href="#運行級別" aria-label="Permalink to “運行級別”">​</a></h3><p>你可以指定不同的運行級別，默認運行級別是 <code>5</code> （多用户圖形界面）。<code>1</code> 啓動到“單用户”模式，它會啓動進入 root shell。<code>3</code> 提供了一個多用户命令列系統。</p><h3 id="從命令列切換" tabindex="-1">從命令列切換 <a class="header-anchor" href="#從命令列切換" aria-label="Permalink to “從命令列切換”">​</a></h3><p>在某個時候，你可能想要運行顯示管理器來再次使用 GUI，最快的方法是運行這個：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ sudo init 5</span></span></code></pre></div><p>就這麼簡單。就我個人而言，我發現命令列比使用 GUI 工具更令人興奮和上手。不過，這只是我的個人偏好。</p><hr>',7)),o("p",null,[n[4]||(n[4]=t("via: ",-1)),i(l,{href:"http://www.linuxandubuntu.com/home/how-to-boot-into-linux-command-line"},{default:e(()=>[...n[3]||(n[3]=[t("http://www.linuxandubuntu.com/home/how-to-boot-into-linux-command-line",-1)])]),_:1})]),o("p",null,[n[8]||(n[8]=t("作者：",-1)),i(l,{href:"http://www.linuxandubuntu.com"},{default:e(()=>[...n[5]||(n[5]=[t("LinuxAndUbuntu",-1)])]),_:1}),n[9]||(n[9]=t(" 譯者：",-1)),i(l,{href:"https://github.com/geekpi"},{default:e(()=>[...n[6]||(n[6]=[t("geekpi",-1)])]),_:1}),n[10]||(n[10]=t(" 校對：",-1)),i(l,{href:"https://github.com/wxy"},{default:e(()=>[...n[7]||(n[7]=[t("wxy",-1)])]),_:1})]),o("p",null,[n[13]||(n[13]=t("本文由 ",-1)),i(l,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...n[11]||(n[11]=[t("LCTT",-1)])]),_:1}),n[14]||(n[14]=t(" 原創編譯，",-1)),i(l,{href:"https://linux.cn/"},{default:e(()=>[...n[12]||(n[12]=[t("Linux中國",-1)])]),_:1}),n[15]||(n[15]=t(" 榮譽推出",-1))])])}const C=a(p,[["render",m]]);export{L as __pageData,C as default};
